     * 查询个例全部报告（按提交顺序）。
     */
    public List<PvReport> findByCaseId(long caseId) {
        return jdbc.query(
                "SELECT " + COLUMNS + " FROM pv_report WHERE case_id = ? ORDER BY id", MAPPER, caseId);
    }
}

